#include <bits/stdc++.h>
using namespace std;
struct Job{int t,s,idx;};
int main(){
    int cases; cin>>cases;
    for(int c=0;c<cases;c++){
        int n; cin>>n;
        vector<Job> jobs(n);
        for(int i=0;i<n;i++){ cin>>jobs[i].t>>jobs[i].s; jobs[i].idx=i+1; }
        stable_sort(jobs.begin(), jobs.end(), [](const Job&a, const Job&b){
            return (long long)a.s*b.t > (long long)b.s*a.t;
        });
        if (c) cout << "\n";
        for(int i=0;i<n;i++) cout << jobs[i].idx << (i+1<n? " ":"\n");
    }
}

